{
  "constraints": [
    {
      "constraint": "图像中必须存在至少一个可辨识的阿斯顿马丁品牌标记；标记形式只能是带中央品牌名条/字样的左右对称展翅徽标，或“Aston Martin/阿斯顿马丁”文字标识。",
      "polarity": "must_have",
      "variants": [
        "带中央品牌名条的展翅徽标",
        "文字标识"
      ],
      "source": "common_sense"
    },
    {
      "constraint": "图像中不得出现拼写错误、乱码、变形或缺字的阿斯顿马丁文字标识。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "图像中的阿斯顿马丁主体车辆或主品牌标识不得带有其他汽车品牌专属徽标作为主标识（如奔驰三叉星、宝马蓝白圆标、法拉利跃马、兰博基尼牛标、保时捷盾徽、宾利带B翅膀等）。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "图像中不得将阿斯顿马丁徽标画成马形、圆形、盾形、星形、螺旋桨形、带其他品牌字母的翅膀或非左右对称翅膀。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    }
  ]
}
